class Wallet:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def add(self, amount):
        self.balance += amount

    def spend(self, amount):
        if amount <= self.balance:
            self.balance -= amount
            return True
        return False

    def summary(self):
        return self.owner + " has " + str(self.balance)

